  const formatResult = dtf.formatToParts(date)
  const filled = []
  for (let i=0;i<formatResult.length;i+=1){ const {type,value}=formatResult[i]; const pos=typeToPos[type]; if(pos>=0) filled[pos]=parseInt(value,10) }
  const utcString = `${filled[0]}-${filled[1]}-${filled[2]} ${filled[3]}:${filled[4]}:${filled[5]}:000`
  const utcTs = dayjs.utc(utcString).valueOf()
  let asTS = +date
  const over = asTS % 1000
  asTS -= over
